from datetime import date, timedelta

class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (availability_date, points)
        self._earned = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")
        points = int(amount)  # 1 point per currency unit, rounded down
        available_on = day + timedelta(days=14)
        self._earned.setdefault(customer, []).append((available_on, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        total = 0
        for available_on, points in self._earned.get(customer, []):
            if available_on <= day:
                total += points
        return total

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points <= 0 or points % 100 != 0:
            raise ValueError("Points must be a positive multiple of 100")
        if points > self.balance(customer, day):
            raise ValueError("Insufficient points")

        remaining = points
        entries = self._earned.get(customer, [])
        # Spend oldest available points first (FIFO)
        for i, (available_on, pts) in enumerate(entries):
            if remaining == 0:
                break
            if available_on <= day and pts > 0:
                used = min(pts, remaining)
                entries[i] = (available_on, pts - used)
                remaining -= used

        # Clean up entries with zero points
        self._earned[customer] = [
            (d, p) for (d, p) in entries if p > 0
        ]
